bSearch(a,left, right, x){
  if left = right then{
    if a[left] = x return left; else return NOT_FOUND;
  }
  mid = (left + right)/2;
  if a[mid] = x then return mid;
  if a[mid] < x return bSearch(a,mid+1, right, x);
