void dfs(int s, int ps){
    // DFS from s with ps is the parent of s in the DFS tree
    t++;
    num[s] = t;
    low[s] = num[s];
    visited[s] = true;
    for(int i = 0;i < A[s].size(); i++){
       int v = A[s][i];
       if(v == ps) continue;
       if(visited[v]){
           low[s] = min(low[s],num[v]);
       }else{
           dfs(v,s);
           low[s] = min(low[s],low[v]);
           if(low[v] > num[s]){
               // discover a bridge (s,v)
               bridges.push_back(make_pair(s,v));
           }
       }
    }
}
